        public static let command = WsCommand.statsVaultTrends

        public struct Payload: Codable, Hashable, Sendable {
            /// Vault id. Minimum 0.
            public var vaultID: Int64
            /// Trend window in hours: default 168 (also for 0), clamped to 1..720. Minimum 0.
            public var windowHours: Int64?

            public init(vaultID: Int64, windowHours: Int64? = nil) {
                self.vaultID = vaultID
                self.windowHours = windowHours
            }

            enum CodingKeys: String, CodingKey {
                case vaultID = "vault_id"
                case windowHours = "window_hours"
            }
        }

        public struct Response: Codable, Hashable, Sendable {
            /// null while there is no data for the vault yet. Always sent; nil is null.
            public var stats: WsModel.StatsTrends?

            public init(stats: WsModel.StatsTrends? = nil) {
                self.stats = stats
            }

            enum CodingKeys: String, CodingKey {
                case stats
            }

            public init(from decoder: any Decoder) throws {
                let container = try decoder.container(keyedBy: CodingKeys.self)
                self.stats = try container.decode(WsModel.StatsTrends?.self, forKey: .stats)
            }

            public func encode(to encoder: any Encoder) throws {
                var container = encoder.container(keyedBy: CodingKeys.self)
                try container.encode(self.stats, forKey: .stats)
            }
        }
    }
}
